import{_ as r,o as a,c as _,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2017Q1 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2017Q1 Ceph社区季度进展报告","date":"2017-03-01T00:00:00.000Z","updated":"2017-03-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017Q1_Ceph社区季度总结.md","filePath":"posts/2017/2017Q1_Ceph社区季度总结.md","lastUpdated":1780460162000}'),l={name:"posts/2017/2017Q1_Ceph社区季度总结.md"};function t(h,e,m,s,i,n){return a(),_("div",null,[...e[0]||(e[0]=[o('<h1 id="ceph-社区-2017q1-季度进展报告" tabindex="-1">Ceph 社区 2017Q1 季度进展报告 <a class="header-anchor" href="#ceph-社区-2017q1-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2017Q1 季度进展报告&quot;">​</a></h1><h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本报告基于 2016 年第四季度至 2017 年第一季度（2016 年 9 月 — 2017 年 3 月）的 Ceph 性能周会及技术讲座材料整理而成，涵盖 BlueStore、RocksDB、RDMA、RBD、RGW 等核心方向的进展。</p><hr><h2 id="一、本季度重点议题" tabindex="-1">一、本季度重点议题 <a class="header-anchor" href="#一、本季度重点议题" aria-label="Permalink to &quot;一、本季度重点议题&quot;">​</a></h2><p><strong>BlueStore 成熟化</strong> 是本季度最核心的主线。从 2016 年 Q4 开始，BlueStore 从实验性后端逐步走向生产就绪，Nokia 等外部用户已开始在云 DVR 场景中进行实际测试，目标是将其作为 Luminous 版本的官方存储后端。详见 <a href="./2016-NOV-23_-_Ceph_Performance_Weekly.html">2016-NOV-23_-_-Ceph_Performance_Weekly</a> 和 <a href="/VideoSummary/posts/2017/2017-FEB-22_-_-_Ceph_Performance_Weekly.html">2017-FEB-22_-_-_Ceph_Performance_Weekly</a>)。</p><p><strong>RocksDB 调优与替代方案探索</strong> 贯穿整个季度。团队持续讨论 RocksDB 的 WAL 优化、column families、压缩策略，同时评估 ZetaScale（Sandisk）作为潜在替代方案。详见 <a href="/VideoSummary/posts/2017/2016-NOV-09_-_-_Ceph_Performance_Weekly.html">2016-NOV-09_-_-_Ceph_Performance_Weekly</a>) 和 <a href="/VideoSummary/posts/2017/2016-OCT-16_-_-_Ceph_Performance_Weekly.html">2016-OCT-16_-_-_Ceph_Performance_Weekly</a>)。</p><p><strong>异步消息传递与 RDMA</strong> 是另一条重要主线，Igor 持续推进 RDMA async messenger 的实现，作为 XIO 的替代方案。</p><p><strong>内存管理系统化</strong> 也是本季度的重点，包括 slab containers、内存池跟踪、OSD 内存预算等工作。</p><hr><h2 id="二、技术亮点" tabindex="-1">二、技术亮点 <a class="header-anchor" href="#二、技术亮点" aria-label="Permalink to &quot;二、技术亮点&quot;">​</a></h2><h3 id="bluestore" tabindex="-1">BlueStore <a class="header-anchor" href="#bluestore" aria-label="Permalink to &quot;BlueStore&quot;">​</a></h3><ul><li><strong>Short Extent Map</strong> 优化合并，显著改善小随机写性能，相比 FileStore 提升约 20-25%。见 <a href="/VideoSummary/posts/2017/2016-SEP-14_-_-_Ceph_Performance_Weekly.html">2016-SEP-14_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>并行事务提交</strong>功能开发推进，移除了 BlueStore 中的同步事务提交路径，性能有所提升。见 <a href="/VideoSummary/posts/2017/2016-NOV-09_-_-_Ceph_Performance_Weekly.html">2016-NOV-09_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>AIO 读取优化</strong>合并，顺序读取性能显著提升。见 <a href="/VideoSummary/posts/2017/2017-FEB-01_-_-_Ceph_Performance_Weekly.html">2017-FEB-01_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>位图分配器（Bitmap Allocator）</strong> 持续优化，RestMap 简化计数和分配单元，预期大幅提升性能。</li><li><strong>BlueStore 启动速度优化</strong>进入讨论，计划通过批处理延迟写入减少初始化时间。见 <a href="./2017-MAR-08_-_Ceph_Performance_Weekly.html">2017-MAR-08_-_-_Ceph_Performance_Weekly</a>。</li><li>Nokia 团队在云 DVR 场景下完成 BlueStore 实际测试，大型对象写入性能约为 FileStore 的两倍，稳定性更好。见 <a href="/VideoSummary/posts/2017/2016-NOV-23_-_-_Ceph_Performance_Weekly.html">2016-NOV-23_-_Ceph_Performance_Weekly</a>)。</li></ul><h3 id="rocksdb" tabindex="-1">RocksDB <a class="header-anchor" href="#rocksdb" aria-label="Permalink to &quot;RocksDB&quot;">​</a></h3><ul><li><strong>Column Families</strong> 基本实现，压缩流量分析显示约 1/3 来自 Omap，约 2/3 来自元数据操作。见 <a href="/VideoSummary/posts/2017/2016-NOV-16_-_-_Ceph_Performance_Weekly.html">2016-NOV-16_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>RocksDB 范围删除操作</strong>（range delete）引入讨论，计划添加配置开关控制是否启用。见 <a href="/VideoSummary/posts/2017/2017-MAR-08_-_-_Ceph_Performance_Weekly.html">2017-MAR-08_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>WAL 优化</strong>测试表明增加日志数量或大小可提升性能。见 <a href="/VideoSummary/posts/2017/2016-OCT-12_-_-_Ceph_Performance_Weekly.html">2016-OCT-12_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>ZetaScale 集成</strong>测试取得进展，在 4K 随机 I/O 场景下已超越 BlueStore+RocksDB 组合。见 <a href="/VideoSummary/posts/2017/2016-OCT-16_-_-_Ceph_Performance_Weekly.html">2016-OCT-16_-_-_Ceph_Performance_Weekly</a>)。</li></ul><h3 id="osd-与-rados" tabindex="-1">OSD 与 RADOS <a class="header-anchor" href="#osd-与-rados" aria-label="Permalink to &quot;OSD 与 RADOS&quot;">​</a></h3><ul><li><strong>Fast Dispatch</strong> 优化持续推进，Sage 与 Greg 合作完成大量代码审查，性能测试显示异步消息传递性能提升约 40%。见 <a href="/VideoSummary/posts/2017/2016-OCT-16_-_-_Ceph_Performance_Weekly.html">2016-OCT-16_-_-_Ceph_Performance_Weekly</a>) 和 <a href="/VideoSummary/posts/2017/2017-FEB-15_-_-_Ceph_Performance_Weekly.html">2017-FEB-15_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>CRUSH 锁移除</strong>工作推进，有望减少锁竞争开销。</li><li><strong>PG 统计（PG stats）更新优化</strong>，将频繁更新与不频繁更新字段分离，减少写入量。见 <a href="/VideoSummary/posts/2017/2016-SEP-07_-_-_Ceph_Performance_Weekly.html">2016-SEP-07_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>LTng 跟踪点</strong>引入 IO 路径，用于函数级延迟分析和 OID 飞行路径追踪。见 <a href="/VideoSummary/posts/2017/2016-DEC-07_-_-_Ceph_Performance_Weekly.html">2016-DEC-07_-_-_Ceph_Performance_Weekly</a>)。</li></ul><h3 id="内存管理" tabindex="-1">内存管理 <a class="header-anchor" href="#内存管理" aria-label="Permalink to &quot;内存管理&quot;">​</a></h3><ul><li><strong>Slab Containers</strong> PR 提交，旨在减少内存碎片，更精细地跟踪内存分配。见 <a href="/VideoSummary/posts/2017/2016-OCT-16_-_-_Ceph_Performance_Weekly.html">2016-OCT-16_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>内存池（Memory Pool）</strong> 机制引入，将 BlueStore 数据移入独立内存池以便跟踪。见 <a href="./2016-NOV-09_-_Ceph_Performance_Weekly.html">2016-NOV-09_-_-_Ceph_Performance_Weekly</a>。</li><li><strong>Ice Age 项目</strong>讨论 OSD 内存预算管理，提出基于总缓存大小动态调整 RocksDB 内存使用量。见 <a href="/VideoSummary/posts/2017/2016-SEP-28_-_-_Ceph_Performance_Weekly.html">2016-SEP-28_-_-_Ceph_Performance_Weekly</a>)。</li></ul><h3 id="rbd" tabindex="-1">RBD <a class="header-anchor" href="#rbd" aria-label="Permalink to &quot;RBD&quot;">​</a></h3><ul><li><strong>EC（Erasure Coding）覆盖写</strong>测试显示大型顺序写性能良好，小随机写仍有差距。见 <a href="/VideoSummary/posts/2017/2016-DEC-14_-_-_Ceph_Performance_Weekly.html">2016-DEC-14_-_-_Ceph_Performance_Weekly</a>)。</li><li>**写回节流（writeback throttle）**调优，通过调整参数平衡吞吐量与读延迟。见 <a href="/VideoSummary/posts/2017/2017-FEB-22_-_-_Ceph_Performance_Weekly.html">2017-FEB-22_-_-_Ceph_Performance_Weekly</a>)。</li></ul><h3 id="大数据与生态" tabindex="-1">大数据与生态 <a class="header-anchor" href="#大数据与生态" aria-label="Permalink to &quot;大数据与生态&quot;">​</a></h3><ul><li><strong>Luxio 项目</strong>介绍，提供统一存储接口连接 HDFS、Swift 等系统，与 Spark 集成后数据访问速度提升超 30 倍（百度案例）。见 <a href="/VideoSummary/posts/2017/2017-FEB-23_--_Ceph_Tech_Talks_-_Big_Data_Analytics.html">2017-FEB-23_--Ceph_Tech_Talks_-_Big_Data_Analytics</a>)。</li></ul><hr><h2 id="三、重要决策与里程碑" tabindex="-1">三、重要决策与里程碑 <a class="header-anchor" href="#三、重要决策与里程碑" aria-label="Permalink to &quot;三、重要决策与里程碑&quot;">​</a></h2><ul><li><strong>BlueStore 确定为 Luminous 默认后端</strong>：Nokia 等外部用户的测试验证了 BlueStore 的生产可用性，社区明确将其作为 Luminous 版本的官方存储后端目标。见 <a href="/VideoSummary/posts/2017/2016-NOV-23_-_-_Ceph_Performance_Weekly.html">2016-NOV-23_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>RocksDB 继续作为 BlueStore 的 KV 引擎</strong>：尽管评估了 WiredTiger、TokuDB、ZetaScale 等替代方案，社区决定在 Luminous 中继续使用 RocksDB，同时持续改进。见 <a href="/VideoSummary/posts/2017/2016-DEC-14_-_-_Ceph_Performance_Weekly.html">2016-DEC-14_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>FIO 引擎合并</strong>：可用于 BlueStore 及其他对象存储的性能基准测试。见 <a href="/VideoSummary/posts/2017/2016-SEP-21_-_-_Ceph_Performance_Weekly.html">2016-SEP-21_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>Zipkin 追踪</strong>工作接近合并，将为分布式追踪提供支持。</li><li><strong>CRC32 优化</strong>确定使用 Intel 指令集加速，提升校验计算性能。见 <a href="/VideoSummary/posts/2017/2017-MAR-08_-_-_Ceph_Performance_Weekly.html">2017-MAR-08_-_Ceph_Performance_Weekly</a>)。</li></ul><hr><h2 id="四、社区动态" tabindex="-1">四、社区动态 <a class="header-anchor" href="#四、社区动态" aria-label="Permalink to &quot;四、社区动态&quot;">​</a></h2><ul><li><strong>Ceph Tech Talk系列重启</strong>：2017 年 1 月 26 日举办了年度首场技术讲座，主题为 Ceph 开发入门，面向新贡献者介绍完整的开发流程（fork、编译、vstart 测试集群、PR 提交等）。见 <a href="/VideoSummary/posts/2017/2017-JAN-26_--_Ceph_Tech_Talk_-_Getting_Started_with_Ceph_Development.html">2017-JAN-26_--<em>Ceph_Tech_Talk</em>-_Getting_Started_with_Ceph_Development</a>)。</li><li><strong>2017 年 2 月 23 日大数据技术讲座</strong>：介绍 Luxio 项目与 Ceph/Swift 集成，吸引了大数据方向的社区关注。见 <a href="/VideoSummary/posts/2017/2017-FEB-23_--_Ceph_Tech_Talks_-_Big_Data_Analytics.html">2017-FEB-23_--<em>Ceph_Tech_Talks</em>-_Big_Data_Analytics</a>)。</li><li><strong>Nokia 深度参与</strong>：Nokia 团队（Ben Jenkins等）持续参与 BlueStore 测试，提供云 DVR 真实场景的反馈，成为本季度重要的外部贡献力量。见 <a href="/VideoSummary/posts/2017/2016-NOV-23_-_-_Ceph_Performance_Weekly.html">2016-NOV-23_-_-_Ceph_Performance_Weekly</a>) 和 <a href="/VideoSummary/posts/2017/2017-FEB-22_-_-_Ceph_Performance_Weekly.html">2017-FEB-22_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>UC Santa Cruz 合作</strong>：与 UC Santa Cruz 研究人员合作探索对象存储分层存储技术。见 <a href="/VideoSummary/posts/2017/2017-MAR-08_-_-_Ceph_Performance_Weekly.html">2017-MAR-08_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>CBT（Ceph Benchmarking Tool）改进</strong>：Ben 开发更可配置的监控框架，Josh 研究将 CBT 恢复功能与新监控框架结合。见 <a href="/VideoSummary/posts/2017/2016-SEP-21_-_-_Ceph_Performance_Weekly.html">2016-SEP-21_-_-_Ceph_Performance_Weekly</a>)。</li><li><strong>RDMA 开发</strong>：Igor 持续推进 RDMA async messenger，添加性能计数器和零拷贝代码，讨论更合理的 RDMA 缓冲区默认值。见 <a href="/VideoSummary/posts/2017/2017-FEB-22_-_-_Ceph_Performance_Weekly.html">2017-FEB-22_-_-_Ceph_Performance_Weekly</a>)。</li></ul><hr><h2 id="五、下季度展望" tabindex="-1">五、下季度展望 <a class="header-anchor" href="#五、下季度展望" aria-label="Permalink to &quot;五、下季度展望&quot;">​</a></h2><p>基于本季度的讨论方向，预计 2017Q 将重点推进以下工作：</p><ol><li><p><strong>Luminous 版本冲刺</strong>：BlueStore 作为默认后端的最终稳定化工作，包括位图分配器锁竞争修复、启动速度优化、延迟写入批处理等遗留问题的解决。</p></li><li><p><strong>RocksDB Column Families 稳定化</strong>：修复 Cupid 分配器等已知 bug，完成 column families 的生产就绪验证。</p></li><li><p><strong>Fast Dispatch 正式合并</strong>：Sage 与 Greg 的合作已接近尾声，预计将在下季度完成合并并进行系统性能测试。</p></li><li><p><strong>RDMA 异步消息传递</strong>：Igor 的工作预计进入更广泛的测试阶段，可能成为高性能网络场景的重要选项。</p></li><li><p><strong>内存管理框架完善</strong>：Ice Age 项目的内存预算管理方案预计进入实现阶段，OSD 内存使用将更加可控。</p></li><li><p><strong>ZetaScale 评估结论</strong>：Sandisk ZetaScale 的集成测试将给出更明确的结论，决定是否作为 RocksDB 的补充或替代方案。</p></li><li><p><strong>RGW 性能专项</strong>：本季度 RGW 性能讨论相对较少，预计下季度将有更多针对对象存储网关的专项优化工作。</p></li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2017/2016-DEC-07_-_-_Ceph_Performance_Weekly.html">2016-DEC-07 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-DEC-14_-_-_Ceph_Performance_Weekly.html">2016-DEC-14 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-NOV-09_-_-_Ceph_Performance_Weekly.html">2016-NOV-09 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-NOV-16_-_-_Ceph_Performance_Weekly.html">2016-NOV-16 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-NOV-23_-_-_Ceph_Performance_Weekly.html">2016-NOV-23 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-OCT-12_-_-_Ceph_Performance_Weekly.html">2016-OCT-12 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-OCT-16_-_-_Ceph_Performance_Weekly.html">2016-OCT-16 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-SEP-07_-_-_Ceph_Performance_Weekly.html">2016-SEP-07 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-SEP-14_-_-_Ceph_Performance_Weekly.html">2016-SEP-14 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-SEP-21_-_-_Ceph_Performance_Weekly.html">2016-SEP-21 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2016-SEP-28_-_-_Ceph_Performance_Weekly.html">2016-SEP-28 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-FEB-01_-_-_Ceph_Performance_Weekly.html">2017-FEB-01 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-FEB-08_-_-_Ceph_Performance_Weekly.html">2017-FEB-08 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-FEB-15_-_-_Ceph_Performance_Weekly.html">2017-FEB-15 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-FEB-22_-_-_Ceph_Performance_Weekly.html">2017-FEB-22 :: Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-FEB-23_--_Ceph_Tech_Talks_-_Big_Data_Analytics.html">2017-FEB-23 -- Ceph Tech Talks: Big Data Analytics</a>)</li><li><a href="/VideoSummary/posts/2017/2017-JAN-26_--_Ceph_Tech_Talk_-_Getting_Started_with_Ceph_Development.html">2017-JAN-26 -- Ceph Tech Talk: Getting Started with Ceph Development</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAR-01_-_-_Ceph_Performance_Weekly.html">2017-MAR-01 -- Ceph Performance Weekly</a>)</li><li><a href="/VideoSummary/posts/2017/2017-MAR-08_-_-_Ceph_Performance_Weekly.html">2017-MAR-08 :: Ceph Performance Weekly</a>)</li></ul>',36)])])}const f=r(l,[["render",t]]);export{c as __pageData,f as default};
